INSERT INTO public.scenarios (
  scenario_code, subject, competency, developmental_band, difficulty,
  prompt, options, learning_objective, hint,
  irt_a, irt_b, irt_c, is_active, usage_count
) VALUES
('ENG-78-SYN-01', 'English Literacy', 'synthesis', '7-8', 'standard', 'Text 1: "Urban heat islands amplify nighttime temperatures by up to 6°C due to the thermal mass of concrete, brick, and asphalt." Text 2: "Cities that mandate extensive green living roofs and high-albedo reflective pavements record a 35% reduction in commercial HVAC cooling energy demand." What holistic conclusion connects these texts?', '[{"text":"Asphalt must be replaced exclusively with deep subterranean drainage tunnels.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Air conditioning units are the sole structural cause of urban heat retention.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Passive architectural and material interventions in urban surfaces can effectively mitigate heat island intensity while slashing municipal energy consumption.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Nighttime temperatures have no measurable bearing on metropolitan energy consumption.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing urban thermodynamic data with sustainable architectural policy.', 'Connect the heat-absorbing concrete in Text 1 with the living roofs/albedo in Text 2.', 1.35, 0.2, 0.25, true, 0),
('ENG-78-SYN-02', 'English Literacy', 'synthesis', '7-8', 'standard', 'Study Alpha: "Microplastic particles under 50 micrometers are ingested by pelagic zooplankton." Study Beta: "Zooplankton form the primary trophic foundation for juvenile herring and mackerel, which are subsequently consumed by apex predatory tuna and humans." What overarching food-web deduction is established?', '[{"text":"Zooplankton populations expand rapidly when feeding on industrial polyester fibers.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Apex predatory tuna are biologically equipped to metabolize synthetic petroleum plastics into protein.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Microplastic pollution bioaccumulates and biomagnifies upward through trophic marine levels, ultimately threatening human nutritional chains.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Microplastics remain permanently confined to seabed sediment layers without entering fauna.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Tracing ecological contamination across multiple trophic levels.', 'Follow the chain: plastic -> zooplankton -> small fish -> tuna -> humans.', 1.35, 0.1, 0.25, true, 0),
('ENG-78-SYN-03', 'English Literacy', 'synthesis', '7-8', 'standard', 'Economic Ledger: "Raw copper prices rose 45% due to supply chain mine strikes in the Andes." Industrial Bulletin: "Manufacturer Q shifted its residential electrical wiring lines from copper core to copper-clad aluminum alloy." What synthesized explanation accounts for Manufacturer Q''s engineering transition?', '[{"text":"Manufacturer Q redesigned product materials to substitute cheaper composite metals in response to soaring raw copper costs.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Aluminum is a superior electrical conductor compared to pure copper in all industrial environments.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Andean copper mines produce only aluminum alloy ore.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The government mandated that all copper must be preserved for sculpture monuments.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing macroeconomic commodity spikes with industrial material substitution.', 'Why would a manufacturer use copper-clad aluminum right when copper prices shoot up 45%?', 1.4, 0.3, 0.25, true, 0),
('ENG-78-SYN-04', 'English Literacy', 'synthesis', '7-8', 'standard', 'Botanical Observation: "Epiphytic orchids possess specialized spongy roots (velamen) that absorb ambient water vapor directly from humid air." Climatological Data: "Cloud forest deforestation caused a 25% drop in local ambient relative humidity over five years." What will be the consequence for indigenous cloud forest orchids?', '[{"text":"Orchid flowering cycles will accelerate because sunlight is increased.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The orchids will immediately grow deep terrestrial taproots into the bedrock.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The orchids will suffer severe hydration stress and population decline because their aerial root mechanisms require high ambient humidity.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"The velamen tissue will transform into photosynthetic broad leaves.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing physiological botanical mechanisms with microclimate degradation.', 'If orchids get water from humidity, what happens when deforestation dries out the air?', 1.4, 0.2, 0.25, true, 0),
('ENG-78-SYN-05', 'English Literacy', 'synthesis', '7-8', 'advanced', 'Document 1: "The 1883 eruption of Krakatoa injected over 20 million tons of sulfur aerosols into the stratosphere." Document 2: "Global meteorological stations recorded an average planetary surface temperature drop of 1.2°C during 1884, alongside vivid crimson sunsets recorded by painters across Europe." What synthesis bridges these physical and artistic phenomena?', '[{"text":"Stratospheric sulfate aerosols scattered solar radiation globally, causing both physical atmospheric cooling and optical scattering that altered sunset aesthetics worldwide.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Volcanic lava flows warmed European rivers and induced widespread psychological delirium among painters.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Crimson sunsets were caused by coal-burning factories in London rather than Krakatoa.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The temperature drop proved that volcanic eruptions halt planetary greenhouse gas cycles entirely.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing volcanological aerosol dynamics with historical climatology and art history.', 'How do sulfur aerosols in the high atmosphere cause both cooling and reddish skies?', 1.45, 0.4, 0.25, true, 0),
('ENG-78-SYN-06', 'English Literacy', 'synthesis', '7-8', 'advanced', 'Source A: "Acoustic noise from commercial maritime shipping overlaps with the low-frequency vocalization bandwidth of baleen whales (10 Hz to 200 Hz)." Source B: "Endocrinological assays of whale blubber demonstrate a 60% surge in stress hormone glucocorticoids in shipping corridors." What unified conclusion is established?', '[{"text":"Low-frequency shipping sounds improve whale echolocation acuity during oceanic hunting.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Whales deliberately alter their migratory routes to escort commercial container vessels.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Glucocorticoid surges indicate that whales enjoy swimming alongside cargo ship propeller wakes.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Anthropogenic maritime acoustic pollution directly masks vital whale communication, inducing chronic physiological stress.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]}]'::jsonb, 'Synthesizing anthropogenic acoustic data with marine biological endocrinology.', 'Connect frequency overlap (communication masking) with high stress hormones.', 1.5, 0.5, 0.25, true, 0),
('ENG-78-SYN-07', 'English Literacy', 'synthesis', '7-8', 'advanced', 'Theory: "The spacing effect demonstrates that distributed review sessions over time yield significantly superior long-term memory retention compared to massed cramming." Experiment: "Cohort A studied 10 hours in a single Saturday; Cohort B studied 2 hours every other day for 5 days. Tested 30 days later, Cohort B remembered 74% of the vocabulary, while Cohort A remembered 28%." How does the experimental data corroborate the theory?', '[{"text":"It demonstrates that total studying time is the sole determinant of retention regardless of schedule.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"It quantitatively proves that distributed spacing creates more durable synaptic memory traces than equivalent time spent in massed cramming.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"It shows that vocabulary acquisition is biologically impossible over weekend study blocks.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"It proves that Cohort A was composed of students with lower baseline cognitive capacity.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing cognitive psychological theory with empirical quantitative retention tests.', 'Compare equal study time (10 hours) distributed vs crammed.', 1.5, 0.6, 0.25, true, 0),
('ENG-78-SYN-08', 'English Literacy', 'synthesis', '7-8', 'olympiad', 'Linguistic Text: "Old English (circa 800 CE) utilized complex inflectional grammatical cases and grammatical gender." Historical Text: "Following the 1066 Norman Conquest, Old French became the prestige language of royal administration, while Anglo-Saxon commoners and Scandinavian settlers interacted daily in multilingual trade marketplaces." What synthesized sociolinguistic mechanism explains the subsequent loss of complex inflections in Middle English?', '[{"text":"Grammatical gender was abolished by ecclesiastical decree from the Archbishop of Canterbury.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The Norman kings passed strict penal codes making the use of Old English inflectional suffixes a capital offense.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Everyday pragmatic communication across diverse linguistic populations favored structural leveling and simplified morphological endings in favor of rigid word order.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Old English was preserved with zero structural modifications inside monastic scriptoria.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing historical sociolinguistics, contact linguistics, and morphological leveling.', 'When speakers of different languages must trade daily, what happens to complex word endings?', 1.6, 0.8, 0.25, true, 0),
('ENG-78-SYN-09', 'English Literacy', 'synthesis', '7-8', 'olympiad', 'Agricultural Report: "Continuous mono-cropping of corn depletes bioavailable soil nitrogen by 30% annually." Microbiology Study: "Legumes establish symbiotic root nodules with Rhizobium bacteria, converting atmospheric dinitrogen into mineral ammonium." Traditional Agronomy: "Mesoamerican farmers planted maize alongside beans and squash in polycultural ''Three Sisters'' guilds." What scientific rationale validates the traditional Three Sisters guild?', '[{"text":"The nitrogen-fixing legume beans naturally replenish the essential nitrogen exhausted by nutrient-hungry maize, sustaining long-term soil fertility.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Squash leaves absorb groundwater and pump it into the roots of surrounding cornstalks.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Maize produces atmospheric dinitrogen gas that kills root-dwelling Rhizobium bacteria.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Polycultural guilds are practiced purely for visual aesthetic harmony during festival harvest seasons.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing biogeochemical nutrient cycles with historical indigenous agronomy.', 'Connect corn''s nitrogen depletion with bean nodules fixing nitrogen.', 1.65, 0.9, 0.25, true, 0),
('ENG-78-SYN-10', 'English Literacy', 'synthesis', '7-8', 'olympiad', 'Physics Postulate: "Conservation of angular momentum dictates that as a rotating body''s mass concentrates closer to its axis of rotation, its rotational velocity must increase." Astronomical Observation: "When a massive dying star collapses from a radius of 1,000,000 km into a dense neutron star with a radius of only 12 km, its spin period accelerates from months into milliseconds." How does the astronomical observation substantiate the physics postulate?', '[{"text":"The observation disproves the postulate because stellar mass is destroyed during gravitational collapse.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Neutron stars possess magnetic fields that physically drag nearby space-time into rotation.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Dying stars absorb rotational energy from colliding neighboring galaxies during supernova collapse.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The dramatic reduction in radius contracts stellar moment of inertia, forcing extreme spin acceleration to conserve total angular momentum.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]}]'::jsonb, 'Synthesizing foundational physical conservation laws with astrophysics phenomena.', 'Think of an ice skater pulling in their arms: smaller radius -> much faster spin.', 1.7, 1, 0.25, true, 0),
('ENG-78-EVL-01', 'English Literacy', 'evaluatingReflecting', '7-8', 'standard', '"The historian repeatedly describes the medieval parchment manuscript as ''whispering forgotten heresies from beneath centuries of dust.'' What stylistic resonance is achieved by this personification?', '[{"text":"It casts doubt on the archaeological authenticity of the parchment provenance.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It provides literal acoustic decibel measurements of parchment vibration.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It proves that the manuscript was copied by multiple illiterate scribes.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It endows the physical artifact with mysterious agency, historical intimacy, and suppressed ideological drama.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]}]'::jsonb, 'Evaluating the aesthetic and dramatic functions of personification in historical prose.', 'How does describing a book as "whispering forgotten heresies" make the reader feel?', 1.3, 0.1, 0.25, true, 0),
('ENG-78-EVL-02', 'English Literacy', 'evaluatingReflecting', '7-8', 'standard', 'A pharmaceutical advertisement claims: "9 out of 10 doctors surveyed recommend NeuroBoost for morning fatigue!" What critical question must a discerning reader ask to evaluate this claim?', '[{"text":"How many total doctors were surveyed, how were they selected, and was the survey funded by the manufacturer?","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"What color is the packaging of the NeuroBoost capsule box?","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Can NeuroBoost be consumed with carbonated beverages?","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Are the doctors legally licensed to operate motor vehicles?","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Evaluating sample selection bias, statistical validity, and commercial conflicts of interest.', 'If only 10 cherry-picked company doctors were asked, does 9 out of 10 mean anything?', 1.35, 0.2, 0.25, true, 0),
('ENG-78-EVL-03', 'English Literacy', 'evaluatingReflecting', '7-8', 'standard', '"The senator began her speech on the national debt by recalling her grandfather''s tiny general store and how he balanced his physical ledger book by candlelight every Saturday night." What rhetorical strategy is being employed here?', '[{"text":"An objective presentation of audited central bank currency reserves.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"A technical econometric breakdown of foreign bond interest yield curves.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"An appeal to folk nostalgia and homespun common sense to simplify a complex macroeconomic issue into an emotionally relatable moral allegory.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"A formal refutation of commercial bankruptcy jurisprudence.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Deconstructing folksy nostalgic anecdotes as persuasive framing devices in politics.', 'Why talk about a grandfather''s tiny ledger book when debating a multi-trillion national debt?', 1.4, 0.3, 0.25, true, 0),
('ENG-78-EVL-04', 'English Literacy', 'evaluatingReflecting', '7-8', 'standard', 'An author introduces a villain with: "His smile was impeccable, gleaming like polished porcelain, but it never reached the cold, calculating slate of his eyes." What psychological insight does this imagery implant in the reader?', '[{"text":"Duality and deceit: an outward veneer of charm concealing an underlying predatory and unfeeling disposition.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"A clinical dental diagnosis of healthy tooth enamel.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"A sympathetic portrayal of a character suffering from eye strain.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"An objective appraisal of stone carving craftsmanship.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Analyzing facial imagery and emotional dissonance in character characterization.', 'Contrast the gleaming smile with the cold, calculating eyes.', 1.35, 0.2, 0.25, true, 0),
('ENG-78-EVL-05', 'English Literacy', 'evaluatingReflecting', '7-8', 'advanced', '"The op-ed writer opens: ''Either we ban all artificial intelligence development immediately, or we surrender our humanity to silicon overlords.'' Which logical fallacy undermines this polemic?', '[{"text":"Ad hominem attack against individual software developers.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"False dilemma (bifurcation): reducing a multifaceted regulatory issue into two extreme, mutually exclusive choices.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"Circular reasoning that repeats the premise as the conclusion.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Post hoc ergo propter hoc causal confusion.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Identifying false dilemmas and black-and-white fallacies in argumentative discourse.', 'Are those really the only two possible choices for AI?', 1.45, 0.5, 0.25, true, 0),
('ENG-78-EVL-06', 'English Literacy', 'evaluatingReflecting', '7-8', 'advanced', 'In reviewing a contemporary novel, a critic writes: "The author mistakes relentless misery for profound artistry, piling misfortune upon catastrophe without providing a shred of thematic illumination." What is the essence of this critique?', '[{"text":"The author should have written a cheerful children''s comedy instead.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The novel has too few pages to properly develop its characters.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Unrelieved gratuitous suffering does not equate to substantive philosophical or literary insight.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"The book contains grammatical syntax errors in its dialogue.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Evaluating literary criticism and the distinction between melodrama and artistic depth.', 'What is the critic saying about piling on sadness without "thematic illumination"?', 1.5, 0.6, 0.25, true, 0),
('ENG-78-EVL-07', 'English Literacy', 'evaluatingReflecting', '7-8', 'advanced', '"The travel essay concludes: ''We traveled ten thousand miles to photograph pristine wilderness, only to discover our own footprints permanently pressed into the tundra.'' What reflective realization does this closing sentence impart?"', '[{"text":"Regret over failing to wear proper thermal hiking boots.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"An ironic awareness of human ecological complicity: the very act of seeking untouched wilderness inevitably alters and intrudes upon it.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"A practical realization that tundra soil requires paving.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Anger that other tourists arrived at the summit first.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Reflecting on situational irony and human complicity in travel journalism.', 'Notice the irony of going to see "untouched" land only to find you left your footprints on it.', 1.5, 0.5, 0.25, true, 0),
('ENG-78-EVL-08', 'English Literacy', 'evaluatingReflecting', '7-8', 'olympiad', '"The political speechwriter skillfully employed anaphora, opening six consecutive sentences with ''We shall not falter...'' What psychological momentum does this repetitive rhetorical cadence generate?"', '[{"text":"Evidence that the speaker lacked sufficient varied vocabulary to compose prose.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Linguistic fatigue and confusion regarding grammatical sentence syntax.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Cumulative emotional resolve and rhythmic inevitability, rallying collective resolve through rhythmic linguistic reinforcement.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"An attempt to disguise factual inaccuracies in the accompanying statistical appendix.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Evaluating anaphora and rhythmic structural rhetoric in public oratory.', 'What does repeating a strong phrase six times do to a listener''s feelings?', 1.6, 0.8, 0.25, true, 0),
('ENG-78-EVL-09', 'English Literacy', 'evaluatingReflecting', '7-8', 'olympiad', '"To call the corporation''s mass laying off of three thousand factory workers ''a workforce right-sizing optimization'' is to sanitize economic devastation with the clinical dialect of corporate technocracy." What authorial stance is revealed by this indictment?', '[{"text":"A technical defense of executive stock option vesting structures.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Enthusiastic support for corporate managerial efficiency.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Indifference toward labor union contract negotiations.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Fierce moral indignation against dehumanizing corporate euphemisms that disguise human suffering.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]}]'::jsonb, 'Deconstructing technocratic euphemisms and analyzing authorial outrage.', 'Notice words like "sanitize economic devastation" and "clinical dialect".', 1.65, 0.9, 0.25, true, 0),
('ENG-78-EVL-10', 'English Literacy', 'evaluatingReflecting', '7-8', 'olympiad', '"When the satirist praises the dystopian government for ''magnanimously rationing electricity so citizens can rediscover the romance of darkness,'' what rhetorical mechanism is operating?"', '[{"text":"A scientific treatise on the circadian sleep benefits of complete darkness.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Literal praise for municipal renewable energy conservation.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Sarcastic irony: professing admiration for an authoritarian failure to expose its absurdity and oppression.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"Historical nostalgia for medieval pre-electric societies.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Analyzing sustained satirical irony and authorial intent in dystopian literature.', 'Is the author truly romanticizing an authoritarian blackout, or mocking it?', 1.7, 1, 0.25, true, 0)
